import SvgFlow from "./svgflow.vue";
import History from "./history";
export default {
  name: 'FlowFile',
  components: {
    SvgFlow: SvgFlow,
    History: History
  },
  props: {
    showHistory: {
      type: Boolean,
      default: true
    },
    noHover: {
      type: Boolean,
      default: false
    },
    processInsId: {
      type: String,
      default: ''
    },
    businessId: {
      type: String,
      default: ''
    },
    processKey: {
      type: String,
      default: ''
    }
  },
  data: function data() {
    return {
      show: false,
      activeName: 'first'
    };
  },
  watch: {
    processInsId: function processInsId() {
      // console.log(this.processInsId +' ===' + this.processKey + "---" +this.businessId)
      this.show = !this.show;
    }
  },
  methods: {
    showCallTable: function showCallTable() {
      this.$emit('showCallTable');
    },
    filterTableData: function filterTableData() {
      this.$emit('filterTableData');
    },
    getFowFile: function getFowFile() {
      this.$emit('getFowFile');
    },
    close: function close() {
      this.$emit('close');
    }
  }
};
